/* Shared profile vocabulary and transparent, demo-only reputation. */
(function(){
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups=[
 ['Permis et sécurité','Licences and safety',[
 ['driving','Permis de conduire','Driver’s licence'],['forklift','Formation / carte de cariste','Forklift training / card'],['firstaid','Premiers soins / RCR','First aid / CPR'],['construction-safety','Carte de sécurité sur chantier','Construction safety card'],['whmis','Formation SIMDUT','WHMIS training'],['food-safety','Formation hygiène et salubrité alimentaires','Food hygiene and safety training']]],
 ['Restauration','Food service',[
 ['kitchen','Préparation en cuisine','Kitchen preparation'],['dishwashing','Plonge','Dishwashing'],['table-service','Service aux tables','Table service'],['barista','Barista','Barista'],['bar','Service au bar','Bar service'],['food-prep','Mise en place / préparation alimentaire','Food preparation / setup']]],
 ['Manutention et entrepôt','Handling and warehouse',[
 ['orders','Préparation de commandes','Order picking'],['packing','Emballage','Packing'],['inventory','Inventaire','Inventory'],['loading','Chargement et déchargement','Loading and unloading'],['pallet','Transpalette','Pallet jack'],['scanner','Lecteur de codes-barres','Barcode scanner']]],
 ['Construction et entretien','Construction and maintenance',[
 ['construction-helper','Aide sur chantier','Construction helper'],['tools','Utilisation d’outils manuels','Hand tools'],['painting','Peinture','Painting'],['site-cleaning','Nettoyage de chantier','Site cleanup'],['cleaning','Entretien ménager','Cleaning'],['landscaping','Entretien extérieur','Grounds maintenance']]],
 ['Commerce, événements et autres','Retail, events and other',[
 ['service','Service à la clientèle','Customer service'],['checkout','Caisse','Checkout'],['shelves','Mise en rayon','Stocking shelves'],['reception','Accueil','Reception'],['events','Montage / démontage événementiel','Event setup / teardown'],['computer','Outils informatiques de base','Basic computer skills'],['other','Autre compétence','Other skill']]]
];
const reviewCriteria={employee:[['punctual','Ponctualité','Punctuality'],['reliable','Fiabilité / présence','Reliability / attendance'],['quality','Qualité du travail','Quality of work'],['instructions','Respect des consignes','Following instructions'],['safety','Travail sécuritaire','Safe work'],['team','Esprit d’équipe','Teamwork'],['respect','Respect et attitude professionnelle','Respect and professionalism'],['adaptable','Capacité d’adaptation','Adaptability'],['communication','Communication','Communication']],employer:[['welcome','Accueil et respect','Welcome and respect'],['organized','Organisation du quart','Shift organization'],['support','Disponibilité pour aider et répondre','Support and responsiveness'],['accurate','Tâches conformes à l’annonce','Duties match the listing'],['instructions','Consignes claires','Clear instructions'],['safe','Milieu et équipements sécuritaires','Safe workplace and equipment'],['hours','Respect des heures et pauses convenues','Agreed hours and breaks respected'],['communication','Communication','Communication'],['payment','Paiement conforme à l’entente (si reçu)','Payment as agreed (if received)']]};
const word=(fr,en,lang)=>lang==='en'?en:fr;
const label=(id,lang)=>{const x=groups.flatMap(g=>g[2]).find(s=>s[0]===id);return x?x[lang==='en'?2:1]:id};
function skillsForm(profile={},employer=false,lang='fr'){
 const ids=profile.skillIds||[],classes=profile.licenceClasses||[];
 return `<fieldset class="skills-fieldset"><legend>${word(employer?'Compétences et permis recherchés':'Mes compétences et permis',employer?'Skills and licences sought':'My skills and licences',lang)}</legend><p>${word(employer?'Coche les compétences utiles pour tes besoins.':'Coche uniquement ce que tu possèdes ou sais faire.',employer?'Select skills relevant to your staffing needs.':'Select only qualifications you hold or skills you have.',lang)}</p>${groups.map((g,i)=>`<details class="skill-group" ${i===0?'open':''}><summary>${g[lang==='en'?1:0]} <span class="skill-count">(${g[2].filter(s=>ids.includes(s[0])).length})</span></summary><div class="skill-checks">${g[2].map(s=>`<label><input type="checkbox" name="skillIds" value="${s[0]}" ${ids.includes(s[0])?'checked':''}> ${s[lang==='en'?2:1]}</label>`).join('')}</div>${i===0?`<fieldset class="licence-classes" ${ids.includes('driving')?'':'hidden'}><legend>${word('Classe du permis','Licence class',lang)}</legend><div class="skill-checks">${['1','2','3','4A','4B','4C','5','6A','6B','6C','6D','6E'].map(c=>`<label><input type="checkbox" name="licenceClasses" value="${c}" ${classes.includes(c)?'checked':''}> ${word('Classe','Class',lang)} ${c}</label>`).join('')}</div></fieldset>`:''}</details>`).join('')}<label class="other-skill" ${ids.includes('other')?'':'hidden'}>${word('Précise ton autre compétence','Specify your other skill',lang)}<input name="otherSkill" maxlength="160" value="${esc(profile.otherSkill||'')}"></label><small>${word('Compétences déclarées. Les cartes, classes, validités et qualifications requises sont à vérifier entre les participants avant le quart.','Self-declared skills. Participants must check required credentials, classes, validity and qualifications before a shift.',lang)}</small></fieldset>`;
}
function readSkills(f){const allowed=groups.flatMap(g=>g[2].map(x=>x[0]));const skillIds=[...new Set(f.getAll('skillIds'))].filter(id=>allowed.includes(id));const licenceClasses=skillIds.includes('driving')?[...new Set(f.getAll('licenceClasses'))].filter(c=>['1','2','3','4A','4B','4C','5','6A','6B','6C','6D','6E'].includes(c)):[];const otherSkill=skillIds.includes('other')?String(f.get('otherSkill')||'').trim().slice(0,160):'';if(skillIds.includes('driving')&&!licenceClasses.length)throw Error('licence');if(skillIds.includes('other')&&!otherSkill)throw Error('other');return {skillIds,licenceClasses,otherSkill};}
function skillsSummary(p={},lang='fr'){return `<div class="skill-tags">${(p.skillIds||[]).map(id=>`<span>${esc(label(id,lang))}${id==='driving'&&p.licenceClasses?.length?' · '+esc(p.licenceClasses.join(', ')):''}${id==='other'&&p.otherSkill?' · '+esc(p.otherSkill):''}</span>`).join('')}</div>`;}
function phone(s){const value=String(s||'').trim();return /^(?:\d{10}|\d{3}-\d{3}-\d{4})$/.test(value)?value.replace(/-/g,''):null;}
function reviewFields(target,lang='fr'){return `<fieldset class="review-stars"><legend>${word('Note globale (obligatoire)','Overall rating (required)',lang)}</legend><div>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" required><span>${n} ★</span></label>`).join('')}</div></fieldset><fieldset class="review-qualities"><legend>${word('Points positifs observés (facultatif)','Positive qualities observed (optional)',lang)}</legend><div class="skill-checks">${reviewCriteria[target].map(c=>`<label><input type="checkbox" name="qualities" value="${c[0]}"> ${c[lang==='en'?2:1]}</label>`).join('')}</div></fieldset><label>${word('Autres commentaires et précisions (facultatif)','Other comments and details (optional)',lang)}<textarea name="comment" maxlength="500" placeholder="${word('Décris ton expérience, les bons points et ce qui pourrait être amélioré.','Describe your experience, strengths and what could improve.',lang)}"></textarea></label><p class="reputation-tip">${word('Des avis honnêtes et précis aident les deux côtés à choisir. Une bonne expérience mérite des étoiles; aucun avis positif n’est exigé.','Honest, specific reviews help both sides choose. A good experience deserves stars; a positive review is never required.',lang)}</p>`;}
function reviewPreview(target,lang='fr'){return `<section class="review-preview"><h3>${word(target==='employee'?'Critères pour évaluer un employé':'Critères pour évaluer un employeur ou une entreprise',target==='employee'?'Worker review criteria':'Employer or business review criteria',lang)}</h3><p>${word('Ces cases seront disponibles après un quart terminé, avec une note de 1 à 5 étoiles et tes commentaires.','These checkboxes become available after a completed shift, along with a 1–5 star rating and your comments.',lang)}</p><fieldset disabled><legend>${word('Aperçu des choix proposés','Preview of available choices',lang)}</legend><div class="skill-checks">${reviewCriteria[target].map(c=>`<label><input type="checkbox"> ${c[lang==='en'?2:1]}</label>`).join('')}</div></fieldset></section>`;}
function readReview(f,target){const rating=Number(f.get('rating'));if(!Number.isInteger(rating)||rating<1||rating>5)throw Error('rating');return {rating,qualities:[...new Set(f.getAll('qualities'))].filter(id=>reviewCriteria[target].some(c=>c[0]===id)),comment:String(f.get('comment')||'').trim().slice(0,500)};}
function reviewSummary(r,target,lang='fr'){return `<strong>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)} · ${r.rating}/5</strong><div class="skill-tags">${(r.qualities||[]).map(id=>reviewCriteria[target].find(c=>c[0]===id)).filter(Boolean).map(c=>`<span>${c[lang==='en'?2:1]}</span>`).join('')}</div>${r.comment?`<p>${esc(r.comment)}</p>`:''}`;}
const reputation=new Map();
function stats(key){return reputation.get(key)||{sum:0,count:0,reviews:[]};}
function seed(key,average,count){if(!reputation.has(key))reputation.set(key,{sum:average*count,count,reviews:[]});}
function addReview(key,reviewId,review){const s=stats(key);if(s.reviews.some(r=>r.id===reviewId))return false;reputation.set(key,{sum:s.sum+review.rating,count:s.count+1,reviews:[...s.reviews,{...review,id:reviewId}]});return true;}
function score(s){return (s.sum+20)/(s.count+5);}
function rank(items,key){return [...items].sort((a,b)=>score(stats(key(b)))-score(stats(key(a)))||(a.km||0)-(b.km||0)||String(a.id).localeCompare(String(b.id)));}
function badge(key,lang='fr'){const s=stats(key);return `<div class="reputation-badge">${s.count?`★ ${(s.sum/s.count).toFixed(1)} / 5 · ${s.count} ${word('avis fictifs','demo reviews',lang)}`:word('Nouveau · aucun avis','New · no reviews',lang)}</div>${s.reviews.length?`<details><summary>${word('Dernier commentaire de démonstration','Latest demo review',lang)}</summary>${reviewSummary(s.reviews.at(-1),key.startsWith('worker:')?'employee':'employer',lang)}</details>`:''}`;}
function explanation(lang='fr'){return `<details class="ranking-help"><summary>${word('Comment les résultats sont-ils classés?','How are results ranked?',lang)}</summary><p>${word('Tes critères de recherche sont appliqués en premier. Ensuite, la note et le nombre d’avis déterminent l’ordre; à score égal, la proximité départage.','Search criteria are applied first. Then ratings and review counts determine order; distance breaks ties.',lang)}</p><p>${word('Score = (total des étoiles + 20) ÷ (nombre d’avis + 5). Un nouveau profil reçoit un score de départ de 4, sans afficher de fausse note. Notes et commentaires sont fictifs dans cette démo.','Score = (total stars + 20) ÷ (review count + 5). New profiles start with a score of 4 without displaying a fabricated rating. Ratings and comments are fictional in this demo.',lang)}</p></details>`;}
function encourage(lang='fr'){return `<p class="reputation-tip">${word('Construis ta réputation : ponctualité, respect et communication donnent envie de retravailler ensemble. Les bons avis peuvent améliorer ta place dans les résultats.','Build your reputation: punctuality, respect and communication make people want to work together again. Good reviews can improve your place in search results.',lang)}</p>`;}
function confirmDelete(text,onConfirm,lang='fr'){
 const d=document.createElement('dialog');d.className='profile-delete-dialog';d.innerHTML=`<h2>${word('Effacer mon profil?','Delete my profile?',lang)}</h2><p>${esc(text)}</p><p>${word('Démo uniquement : aucun compte réel ne sera supprimé.','Demo only: no real account will be deleted.',lang)}</p><div class="delete-actions"><button type="button" data-cancel>${word('Annuler','Cancel',lang)}</button><button type="button" data-confirm>${word('Effacer ce profil','Delete this profile',lang)}</button></div>`;document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=()=>{try{onConfirm();d.close()}catch{d.querySelector('p').textContent=word('Impossible de vider les données locales. Réessaie après avoir autorisé le stockage du navigateur.','Unable to clear local data. Try again after enabling browser storage.',lang)}};d.addEventListener('close',()=>d.remove());d.showModal();d.querySelector('[data-cancel]').focus();
}
document.addEventListener('change',e=>{const f=e.target.closest('.skills-fieldset');if(!f)return;const driving=f.querySelector('[value="driving"]').checked;f.querySelector('.licence-classes').hidden=!driving;if(!driving)f.querySelectorAll('[name="licenceClasses"]').forEach(x=>x.checked=false);const other=f.querySelector('[value="other"]').checked;f.querySelector('.other-skill').hidden=!other;f.querySelector('[name="otherSkill"]').required=other;f.querySelectorAll('.skill-group').forEach(g=>g.querySelector('.skill-count').textContent='('+g.querySelectorAll('[name="skillIds"]:checked').length+')')});
window.DispoStandards={groups,reviewCriteria,skillsForm,readSkills,skillsSummary,phone,reviewFields,reviewPreview,readReview,reviewSummary,stats,seed,addReview,score,rank,badge,explanation,encourage,confirmDelete};
})();
